from transformers import TrainerCallback
class MyCallback(TrainerCallback):
    def on_epoch_end(self, args, state, control, **kwargs):
        print("Epoch ended!")
print(issubclass(MyCallback, TrainerCallback))

from datasets import Dataset
ds = Dataset.from_dict({"text": ["hello world", "foo bar"]})
def token_len(example):
    return {"len": len(example['text'].split())}
ds = ds.map(token_len)
print(ds[1]['len'])

from datasets import Dataset
ds = Dataset.from_dict({"x": [1, 2, 3, 4, 5]})
def add_one(batch):
    return {"x": [i + 1 for i in batch['x']]}
ds = ds.map(add_one, batched=True, batch_size=2)
print(ds['x'])

from datasets import Dataset
def gen():
    for i in range(100):
        yield {"id": i, "text": f"Sample {i}"}
ds = Dataset.from_generator(gen)
print(len(ds))

from transformers import StoppingCriteria, StoppingCriteriaList
class StopOnToken(StoppingCriteria):
    def __call__(self, input_ids, scores, **kwargs):
        return input_ids[0, -1].item() == 13  # Stop on period
criteria = StoppingCriteriaList([StopOnToken()])
print(isinstance(criteria, StoppingCriteriaList))

